630	    private MvcResult split(String parentKey, String commandKey, List<String[]> children,
631	                            int expected) throws Exception {
632	        return mockMvc.perform(post("/api/batches/" + parentKey + "/split")
633	                        .contentType(MediaType.APPLICATION_JSON)
634	                        .content(splitBody(commandKey, children)))
