 * parents 逐父给出合批落定前的过敏原集合、清洁代次与状态。后续过敏原保存或清洁推进不改写本快照。
 */
public record MergeResponse(
        String requestId,
        String childBatchKey,
        String childBatchNo,
        String productCode,
        List<String> allergens,
        int cleaningGeneration,
        BatchStatus childStatus,
        List<MergeParent> parents,
        Instant mergedAt
) {

    /**
     * 单个父批的冻结依据快照。statusBeforeMerge 固定为 RELEASED；合批落定后父批当前状态为 MERGED。
     */
    public record MergeParent(
            String batchKey,
            String batchNo,
            String productCode,
            List<String> allergens,
            int cleaningGeneration,
            BatchStatus statusBeforeMerge,
            int seq
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 按 requestId 查询合批结果：成功（MERGED）返回首次子批快照；被拒（REJECTED）返回全部 422 拒绝原因。
 * 拒绝不占用 requestId，同一 requestId 可能先被拒多次后成功，成功后不再产生拒绝记录。
 */
public record MergeLookupResponse(
        String requestId,
        String outcome,
        MergeResponse merge,
        List<Rejection> rejections
) {

    /**
     * 单条合批拒绝原因。code 为机器可区分代码，detail 为涉及父批键与实际/期望值的人读说明。
     */
    public record Rejection(
            String reasonCode,
            String reasonDetail,
            Instant rejectedAt
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 过敏原保存结果：返回规范化（trim、去重、字典序稳定排序）后的过敏原集合与当前清洁代次。
 */
public record AllergensResponse(
        String batchKey,
        List<String> allergens,
        int cleaningGeneration,
        Instant updatedAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 清洁代次推进结果。清洁代次为正整数，只允许单调向前。
 */
public record GenerationResponse(
        String batchKey,
        int cleaningGeneration,
        Instant updatedAt
) {
}

