        List<@NotBlank(message = "检验项不能为空") String> requiredTests,
        @Size(max = 20, message = "allergens 至多包含 20 个过敏原")
        List<@NotBlank String> allergens,
        @Positive(message = "cleaningGeneration 必须为正整数")
        Integer cleaningGeneration
) {
}

